  ('b1ad1c9d-6f5a-5eff-8bdf-4c4254c8b1a3', '2d304df6-0555-5f47-b005-5672136e96a9', 2, 'inv-1317-10-the-pyramid', $lf${"en-US":"The pyramid","es-MX":"La pirámide","pt-BR":"A pirâmide"}$lf$::jsonb, $lf${"en-US":"Explain why a scheme that pays earlier members with newer members' money must collapse, and tell it apart from a real business.","es-MX":"Explicar por qué un esquema que paga a los primeros con el dinero de los nuevos tiene que colapsar, y distinguirlo de un negocio real.","pt-BR":"Explicar por que um esquema que paga os primeiros com o dinheiro dos novos precisa desmoronar, e distingui-lo de um negócio real."}$lf$::jsonb, 'teaching', 'draft'),
  ('6fd713ac-46ee-547d-85ff-2bb319711307', '2d304df6-0555-5f47-b005-5672136e96a9', 3, 'inv-1317-11-the-bad-season', $lf${"en-US":"The bad season","es-MX":"La mala temporada","pt-BR":"A temporada ruim"}$lf$::jsonb, $lf${"en-US":"Compare panic selling with waiting during a downturn, and keep a sound plan while rejecting offers that exploit the fear.","es-MX":"Comparar vender en pánico con esperar durante una baja, y mantener un plan sólido rechazando ofertas que se aprovechan del miedo.","pt-BR":"Comparar vender em pânico com esperar durante uma queda, e manter um plano sólido recusando ofertas que exploram o medo."}$lf$::jsonb, 'teaching', 'draft'),
  ('e34f4397-edc0-5ac0-8920-9144d5590c02', '2d304df6-0555-5f47-b005-5672136e96a9', 4, 'inv-1317-12-your-long-term-plan', $lf${"en-US":"Your long-term plan","es-MX":"Tu plan a largo plazo","pt-BR":"Seu plano de longo prazo"}$lf$::jsonb, $lf${"en-US":"Combine a goal, a buffer, a diversified mix, a long horizon and protection from interruptions into one long-term plan.","es-MX":"Combinar una meta, un colchón, una mezcla diversificada, un plazo largo y protección contra interrupciones en un solo plan de largo plazo.","pt-BR":"Combinar uma meta, uma reserva, uma mistura diversificada, um prazo longo e proteção contra interrupções em um único plano de longo prazo."}$lf$::jsonb, 'teaching', 'draft'),
  ('3ab98ab5-b4d1-53c5-9038-65cc4af7a723', 'b3331224-0e13-55ac-847a-c7c543dfc05a', 1, 'inv-adult-01-a-rate-and-ten-years', $lf${"en-US":"A rate and ten years","es-MX":"Una tasa y diez años","pt-BR":"Uma taxa e dez anos"}$lf$::jsonb, $lf${"en-US":"Show how leaving earnings in makes each period's gain grow, and what is lost when growth is interrupted.","es-MX":"Mostrar cómo dejar las ganancias adentro hace crecer la ganancia de cada periodo, y qué se pierde si el crecimiento se interrumpe.","pt-BR":"Mostrar como deixar os ganhos aplicados faz o ganho de cada período crescer, e o que se perde quando o crescimento é interrompido."}$lf$::jsonb, 'teaching', 'draft'),
  ('e0c74f35-d563-58b2-a265-aacb8d135fa8', 'b3331224-0e13-55ac-847a-c7c543dfc05a', 2, 'inv-adult-02-the-cost-of-starting-late', $lf${"en-US":"The cost of starting late","es-MX":"El costo de empezar tarde","pt-BR":"O custo de começar tarde"}$lf$::jsonb, $lf${"en-US":"Compare two people who save the same amount but start at different times, and explain why the earlier start ends with more.","es-MX":"Comparar a dos personas que ahorran lo mismo pero empiezan en momentos distintos, y explicar por qué quien empieza antes termina con más.","pt-BR":"Comparar duas pessoas que poupam o mesmo valor mas começam em momentos diferentes, e explicar por que quem começa antes termina com mais."}$lf$::jsonb, 'teaching', 'draft'),
  ('d5ebcc45-44cf-582a-a9dc-ef132e469abe', 'b3331224-0e13-55ac-847a-c7c543dfc05a', 3, 'inv-adult-03-what-a-rate-really-buys', $lf${"en-US":"What a rate really buys","es-MX":"Lo que de verdad compra una tasa","pt-BR":"O que uma taxa realmente compra"}$lf$::jsonb, $lf${"en-US":"Work out how much a price rose in currency and percent, and add a buffer to a goal so a price rise does not leave it short.","es-MX":"Calcular cuánto subió un precio en dinero y en porcentaje, y agregar un colchón a una meta para que una subida no la deje corta.","pt-BR":"Calcular quanto um preço subiu em dinheiro e em porcentagem, e adicionar uma reserva a uma meta para que uma alta não a deixe curta."}$lf$::jsonb, 'teaching', 'draft'),
  ('1e0dd15a-ae18-543f-9d52-4886fb0fce48', 'b3331224-0e13-55ac-847a-c7c543dfc05a', 4, 'inv-adult-04-what-a-risky-offer-is-worth', $lf${"en-US":"What a risky offer is worth","es-MX":"Cuánto vale una oferta riesgosa","pt-BR":"Quanto vale uma oferta arriscada"}$lf$::jsonb, $lf${"en-US":"Judge a risky option by how often it pays and how much, and explain why one win proves nothing.","es-MX":"Juzgar una opción con riesgo por qué tan seguido paga y cuánto, y explicar por qué ganar una vez no prueba nada.","pt-BR":"Avaliar uma opção com risco por quantas vezes paga e quanto, e explicar por que ganhar uma vez não prova nada."}$lf$::jsonb, 'teaching', 'draft'),
  ('2ac5bf8b-6612-5ccb-9107-3903a22c9c8e', 'd0213480-fc21-50f4-acf6-0089043f4c10', 1, 'inv-adult-05-whats-in-the-basket', $lf${"en-US":"What's in the basket","es-MX":"Qué trae la canasta","pt-BR":"O que tem na cesta"}$lf$::jsonb, $lf${"en-US":"Explain that a share is a small piece of something and a fund is a basket of many pieces that someone manages.","es-MX":"Explicar que una acción es un pedacito de algo y un fondo es una canasta de muchos pedacitos que alguien administra.","pt-BR":"Explicar que uma ação é um pedacinho de algo e um fundo é uma cesta de muitos pedacinhos que alguém administra."}$lf$::jsonb, 'teaching', 'draft'),
  ('b31765ea-0545-5357-b715-bea8cc697633', 'd0213480-fc21-50f4-acf6-0089043f4c10', 2, 'inv-adult-06-test-a-mix-in-the-simulator', $lf${"en-US":"Test a mix in the simulator","es-MX":"Prueba una mezcla en el simulador","pt-BR":"Teste uma mistura no simulador"}$lf$::jsonb, $lf${"en-US":"Choose a mix of safer and riskier pieces for a risk profile, simulate several rounds, and rebalance when the mix drifts.","es-MX":"Elegir una mezcla de piezas más seguras y más arriesgadas según un perfil, simular varias rondas y reequilibrar cuando la mezcla se mueve.","pt-BR":"Escolher uma mistura de partes mais seguras e mais arriscadas para um perfil, simular várias rodadas e rebalancear quando a mistura se desvia."}$lf$::jsonb, 'teaching', 'draft'),
  ('3eb4dff8-422a-5841-aa3c-d340a49096bc', 'd0213480-fc21-50f4-acf6-0089043f4c10', 3, 'inv-adult-07-the-offer-in-the-group-chat', $lf${"en-US":"The offer in the group chat","es-MX":"La oferta en el grupo de chat","pt-BR":"A oferta no grupo de mensagens"}$lf$::jsonb, $lf${"en-US":"Recognize the warning signs of investment fraud, such as guaranteed profit, pressure to decide now and an unexplained source of money, and tell a trusted adult.","es-MX":"Reconocer las señales de fraude en inversiones, como ganancia garantizada, presión para decidir ya y dinero de origen inexplicable, y contarlo a un adulto de confianza.","pt-BR":"Reconhecer os sinais de fraude em investimentos, como lucro garantido, pressão para decidir já e dinheiro de origem inexplicável, e contar a um adulto de confiança."}$lf$::jsonb, 'teaching', 'draft'),
  ('8217223b-1dd2-56b7-9ab3-9154d1c1ef55', 'd0213480-fc21-50f4-acf6-0089043f4c10', 4, 'inv-adult-08-the-plan-in-a-bad-season', $lf${"en-US":"The plan in a bad season","es-MX":"El plan en una mala temporada","pt-BR":"O plano em uma temporada ruim"}$lf$::jsonb, $lf${"en-US":"Compare panic selling with waiting during a downturn, and keep a sound plan while rejecting offers that exploit the fear.","es-MX":"Comparar vender en pánico con esperar durante una baja, y mantener un plan sólido rechazando ofertas que se aprovechan del miedo.","pt-BR":"Comparar vender em pânico com esperar durante uma queda, e manter um plano sólido recusando ofertas que exploram o medo."}$lf$::jsonb, 'teaching', 'draft')
ON CONFLICT DO NOTHING;

